CREATE OR REPLACE FUNCTION public.ediel_messages_set_ack_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  if upper(coalesce(new.message_family, '')) in ('CONTRL', 'APERAK', 'UTILTS_ERR') then
    new.ack_outcome := coalesce(
      nullif(lower(coalesce(new.ack_outcome, '')), ''),
      public.ediel_derive_ack_outcome(
        new.message_family,
        coalesce(new.parsed_payload, '{}'::jsonb),
        new.syntax_check_status,
        new.functional_check_status
      )
    );
  else
    new.ack_outcome := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_acquire_automation_lock(p_lock_key text, p_lock_token uuid, p_company_id uuid DEFAULT NULL::uuid, p_ttl_seconds integer DEFAULT 3600, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := now();
  v_expires timestamptz;
begin
  if nullif(btrim(p_lock_key), '') is null or p_lock_token is null then
    raise exception 'lock_key_and_token_required' using errcode = '22023';
  end if;
  if p_ttl_seconds < 30 or p_ttl_seconds > 86400 then
    raise exception 'lock_ttl_out_of_range' using errcode = '22023';
  end if;
  v_expires := v_now + make_interval(secs => p_ttl_seconds);

  delete from public.automation_locks where expires_at <= v_now;
  insert into public.automation_locks(lock_key, company_id, lock_token, locked_at, expires_at, metadata)
  values (btrim(p_lock_key), p_company_id, p_lock_token, v_now, v_expires, coalesce(p_metadata, '{}'::jsonb))
  on conflict (lock_key) do nothing;
  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_assert_company_operational_for_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_company_status text;
begin
  if new.company_id is null then
    return new;
  end if;

  select status into v_company_status
  from public.companies
  where id = new.company_id;

  if coalesce(v_company_status, 'active') not in ('active', 'onboarding') then
    raise exception 'Tenant % is %, write is blocked for operational data', new.company_id, v_company_status
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_audit_critical_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
      declare
        v_old jsonb := case when TG_OP in ('UPDATE','DELETE') then to_jsonb(OLD) else null end;
        v_new jsonb := case when TG_OP in ('INSERT','UPDATE') then to_jsonb(NEW) else null end;
        v_company_id uuid := null;
        v_actor uuid := null;
        v_entity_id text := null;
      begin
        if TG_TABLE_NAME = 'audit_logs' then
          return coalesce(NEW, OLD);
        end if;

        v_company_id := nullif(coalesce(v_new ->> 'company_id', v_old ->> 'company_id'), '')::uuid;
        if v_company_id is null and TG_TABLE_NAME = 'companies' then
          v_company_id := nullif(coalesce(v_new ->> 'id', v_old ->> 'id'), '')::uuid;
        end if;

        v_actor := nullif(coalesce(
          v_new ->> 'updated_by',
          v_new ->> 'created_by',
          v_new ->> 'actor_user_id',
          v_new ->> 'invited_by',
          v_new ->> 'paused_by',
          v_old ->> 'updated_by',
          v_old ->> 'created_by',
          v_old ->> 'actor_user_id',
          v_old ->> 'invited_by',
          v_old ->> 'paused_by'
        ), '')::uuid;

        v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');

        insert into public.audit_logs (
          company_id,
          actor_user_id,
          entity_type,
          entity_id,
          action,
          old_values,
          new_values,
          metadata
        ) values (
          v_company_id,
          v_actor,
          TG_TABLE_NAME,
          v_entity_id,
          lower(TG_TABLE_NAME || '_' || TG_OP),
          v_old,
          v_new,
          jsonb_build_object(
            'source', 'gridex_audit_critical_row_change',
            'operation', TG_OP,
            'table', TG_TABLE_NAME
          )
        );

        return coalesce(NEW, OLD);
      end;
      $function$

CREATE OR REPLACE FUNCTION public.gridex_billing_underlay_item_gate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  n public.normalized_metering_values%rowtype;
  u public.billing_underlays%rowtype;
  v_value_start_date date;
  v_value_end_date date;
begin
  if new.source_normalized_metering_value_id is null then raise exception 'billing_underlay_source_normalized_value_required' using errcode='23514'; end if;
  select * into n from public.normalized_metering_values where id=new.source_normalized_metering_value_id;
  select * into u from public.billing_underlays where id=new.billing_underlay_id;
  if not found or u.id is null then raise exception 'billing_underlay_missing' using errcode='23503'; end if;
  if n.id is null then raise exception 'billing_underlay_normalized_value_missing' using errcode='23503'; end if;
  if n.company_id<>new.company_id or u.company_id<>new.company_id then raise exception 'billing_underlay_lineage_tenant_mismatch' using errcode='23514'; end if;
  if n.revision_status<>'current' or n.billing_status<>'billable' or n.billing_gate_status<>'eligible' then raise exception 'billing_underlay_value_not_gate_eligible' using errcode='23514'; end if;
  if n.source_message_id is null or n.source_metering_value_id is null or n.supply_period_id is null then raise exception 'billing_underlay_lineage_incomplete' using errcode='23514'; end if;
  if u.supply_period_id is null or u.supply_period_id<>n.supply_period_id then raise exception 'billing_underlay_supply_period_mismatch' using errcode='23514'; end if;

  v_value_start_date := (n.period_start at time zone 'Europe/Stockholm')::date;
  v_value_end_date := (n.period_end at time zone 'Europe/Stockholm')::date;
  if v_value_start_date < u.billing_period_start or v_value_end_date > u.billing_period_end then
    raise exception 'billing_underlay_period_outside_segment'
      using errcode='23514', detail=jsonb_build_object(
        'normalized_metering_value_id',n.id,
        'value_start_date',v_value_start_date,
        'value_end_date',v_value_end_date,
        'billing_period_start',u.billing_period_start,
        'billing_period_end',u.billing_period_end,
        'timezone','Europe/Stockholm',
        'billing_period_end_exclusive',true
      )::text;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_inbound_ediel_rule_pack_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rule_pack_id uuid;
  v_profile_id uuid;
  v_profile_key text;
  v_guide_version text;
  v_guide_revision text;
  v_source_hash text;
  v_effective_date date;
  v_match_count integer;
begin
  if new.direction <> 'inbound' or new.company_id is null or new.message_family not in ('PRODAT','UTILTS') then
    return new;
  end if;

  if new.canonical_rule_pack_id is not null
     and nullif(new.rule_profile_key,'') is not null
     and new.rule_profile_version_id is not null
     and nullif(new.rule_profile_version,'') is not null
     and nullif(new.rule_pack_checksum,'') is not null
     and coalesce(new.rule_pack_snapshot,'{}'::jsonb) <> '{}'::jsonb then
    return new;
  end if;

  v_effective_date := coalesce(new.message_received_at::date, new.created_at::date, current_date);

  select count(*)
  into v_match_count
  from public.ediel_message_profiles mp
  join public.ediel_rule_packs rp on rp.id = mp.rule_pack_id
  where mp.is_enabled = true
    and mp.profile->>'family' = new.message_family
    and mp.message_code = new.message_code
    and mp.direction in ('inbound','both')
    and rp.status in ('active','future')
    and rp.valid_from <= v_effective_date
    and (rp.valid_to is null or rp.valid_to >= v_effective_date);

  if v_match_count <> 1 then
    raise exception 'canonical_inbound_rule_profile_resolution_failed:%:%:%:%',
      new.message_family, coalesce(new.message_code,''), v_effective_date, v_match_count
      using errcode='23514';
  end if;

  select mp.rule_pack_id, mp.id, mp.profile_key, rp.guide_version, rp.guide_revision, rp.source_hash
  into v_rule_pack_id, v_profile_id, v_profile_key, v_guide_version, v_guide_revision, v_source_hash
  from public.ediel_message_profiles mp
  join public.ediel_rule_packs rp on rp.id = mp.rule_pack_id
  where mp.is_enabled = true
    and mp.profile->>'family' = new.message_family
    and mp.message_code = new.message_code
    and mp.direction in ('inbound','both')
    and rp.status in ('active','future')
    and rp.valid_from <= v_effective_date
    and (rp.valid_to is null or rp.valid_to >= v_effective_date)
  limit 1;

  new.canonical_rule_pack_id := v_rule_pack_id;
  new.rule_profile_key := v_profile_key;
  new.rule_profile_version_id := v_profile_id;
  new.rule_profile_version := v_guide_version || ':r' || v_guide_revision;
  new.rule_pack_checksum := v_source_hash;
  new.rule_pack_snapshot := jsonb_build_object(
    'family', new.message_family,
    'code', new.message_code,
    'direction', 'inbound',
    'environment', new.environment,
    'profileKey', v_profile_key,
    'profileVersionId', v_profile_id,
    'version', v_guide_version || ':r' || v_guide_revision,
    'checksum', v_source_hash,
    'authority', 'gridex_bind_inbound_ediel_rule_pack_evidence',
    'databaseRole', 'evidence_only',
    'effectiveDate', v_effective_date
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_capture_ediel_rule_pack_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile_rule_pack_id uuid;
begin
  if new.direction='outbound' and new.message_family in ('PRODAT','UTILTS','CONTRL','APERAK','UTILTS_ERR') then
    if new.company_id is null then
      raise exception 'outbound_ediel_company_id_required' using errcode='23502';
    end if;

    if nullif(new.rule_profile_key,'') is null or new.rule_profile_version_id is null
       or nullif(new.rule_profile_version,'') is null or nullif(new.rule_pack_checksum,'') is null
       or coalesce(new.rule_pack_snapshot,'{}'::jsonb)='{}'::jsonb then
      raise exception 'outbound_ediel_rule_pack_snapshot_required' using errcode='23514';
    end if;

    select mp.rule_pack_id into v_profile_rule_pack_id
    from public.ediel_message_profiles mp
    where mp.id = new.rule_profile_version_id
      and mp.is_enabled = true;

    if v_profile_rule_pack_id is null then
      raise exception 'canonical_ediel_message_profile_required:%', new.rule_profile_version_id using errcode='23503';
    end if;

    if new.canonical_rule_pack_id is null or new.canonical_rule_pack_id <> v_profile_rule_pack_id then
      raise exception 'canonical_ediel_rule_pack_profile_mismatch:%:%', coalesce(new.canonical_rule_pack_id::text,'null'), v_profile_rule_pack_id::text using errcode='23514';
    end if;

    insert into public.ediel_rule_pack_snapshots(
      company_id,ediel_message_id,profile_key,rule_profile_version_id,profile_version,checksum,snapshot
    ) values (
      new.company_id,new.id,new.rule_profile_key,new.rule_profile_version_id,new.rule_profile_version,new.rule_pack_checksum,new.rule_pack_snapshot
    ) on conflict(ediel_message_id) do update set
      company_id=excluded.company_id,
      profile_key=excluded.profile_key,
      rule_profile_version_id=excluded.rule_profile_version_id,
      profile_version=excluded.profile_version,
      checksum=excluded.checksum,
      snapshot=excluded.snapshot;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_billing_export_run(p_run jsonb, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_company_id uuid:=nullif(p_run->>'company_id','')::uuid;
  v_run_id uuid:=coalesce(nullif(p_run->>'id','')::uuid,gen_random_uuid());
  v_existing public.billing_export_runs%rowtype;
  v_run public.billing_export_runs%rowtype;
  v_item jsonb;
  v_underlay public.billing_underlays%rowtype;
  v_item_contract_id uuid;
  v_pricing_run_id uuid;
  v_rows integer:=0;
begin
  if v_company_id is null or nullif(p_run->>'period_month','') is null then
    raise exception using errcode='22023',message='export_company_and_period_required';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then
    raise exception using errcode='22023',message='export_items_must_be_array';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text||':'||coalesce(p_run->>'idempotency_key',v_run_id::text),0));

  if nullif(p_run->>'idempotency_key','') is not null then
    select * into v_existing from public.billing_export_runs
    where company_id=v_company_id and idempotency_key=p_run->>'idempotency_key'
    order by created_at limit 1;
    if found then return to_jsonb(v_existing); end if;
  end if;

  insert into public.billing_export_runs(
    id,company_id,period_month,target_system,export_format,status,rows_total,rows_ready,
    rows_blocked,rows_exported,blocker_summary,metadata,created_by,created_at,updated_at,
    adapter_key,payload_version,retry_policy,idempotency_key
  ) values (
    v_run_id,v_company_id,p_run->>'period_month',coalesce(nullif(p_run->>'target_system',''),'billing_partner'),
    coalesce(nullif(p_run->>'export_format',''),'json'),coalesce(nullif(p_run->>'status',''),'blocked'),
    coalesce((p_run->>'rows_total')::integer,0),coalesce((p_run->>'rows_ready')::integer,0),
    coalesce((p_run->>'rows_blocked')::integer,0),coalesce((p_run->>'rows_exported')::integer,0),
    coalesce(p_run->'blocker_summary','[]'::jsonb),coalesce(p_run->'metadata','{}'::jsonb),
    nullif(p_run->>'created_by','')::uuid,coalesce(nullif(p_run->>'created_at','')::timestamptz,now()),
    coalesce(nullif(p_run->>'updated_at','')::timestamptz,now()),
    coalesce(nullif(p_run->>'adapter_key',''),'gridex_billing_partner_v1'),
    coalesce(nullif(p_run->>'payload_version',''),'billing_export_v4c'),
    coalesce(p_run->'retry_policy','{"maxAttempts":3,"strategy":"manual_retry"}'::jsonb),
    nullif(p_run->>'idempotency_key','')
  ) returning * into v_run;

  for v_item in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    if nullif(v_item->>'billing_underlay_id','') is null then
      raise exception using errcode='23514',message='export_item_underlay_required';
    end if;
    select * into v_underlay from public.billing_underlays
    where id=(v_item->>'billing_underlay_id')::uuid and company_id=v_company_id for share;
    if not found then raise exception using errcode='23503',message='export_item_underlay_not_found_for_tenant'; end if;

    v_item_contract_id:=nullif(v_item->>'contract_id','')::uuid;
    if coalesce(v_item->>'status','blocked')='ready' then
      if v_item_contract_id is null or v_underlay.contract_id is distinct from v_item_contract_id then
        raise exception using errcode='23514',message='export_item_contract_must_match_underlay_exactly';
      end if;
      if coalesce(v_underlay.contract_price_snapshot_id,v_underlay.pricing_snapshot_id) is null then
        raise exception using errcode='23514',message='export_item_exact_price_snapshot_required';
      end if;
      v_pricing_run_id:=nullif(v_item#>>'{payload_snapshot,pricing,pricingRunId}','')::uuid;
      if v_pricing_run_id is null or not exists(
        select 1 from public.pricing_runs pr
        where pr.id=v_pricing_run_id and pr.company_id=v_company_id
          and pr.billing_underlay_id=v_underlay.id and pr.status='locked'
      ) then
        raise exception using errcode='23514',message='export_item_locked_pricing_run_required';
      end if;
    end if;

    insert into public.billing_export_run_items(
      id,company_id,billing_export_run_id,billing_underlay_id,contract_id,customer_id,site_id,metering_point_id,
      status,readiness_status,blocker_reasons,pricing_line_items,invoice_recipient,invoice_email,invoice_reference,
      billing_level,consolidated_invoice,invoice_address_snapshot,site_address_snapshot,consolidated_invoice_group_key,
      adapter_key,payload_version,adapter_payload_snapshot,external_reference,payload_snapshot,export_status,
      idempotency_key,created_at,updated_at
    ) values (
      coalesce(nullif(v_item->>'id','')::uuid,gen_random_uuid()),v_company_id,v_run.id,v_underlay.id,v_item_contract_id,
      nullif(v_item->>'customer_id','')::uuid,nullif(v_item->>'site_id','')::uuid,nullif(v_item->>'metering_point_id','')::uuid,
      coalesce(nullif(v_item->>'status',''),'blocked'),coalesce(nullif(v_item->>'readiness_status',''),'blocked'),
      coalesce(v_item->'blocker_reasons','[]'::jsonb),coalesce(v_item->'pricing_line_items','[]'::jsonb),
      nullif(v_item->>'invoice_recipient',''),nullif(v_item->>'invoice_email',''),nullif(v_item->>'invoice_reference',''),
      coalesce(nullif(v_item->>'billing_level',''),'customer'),coalesce((v_item->>'consolidated_invoice')::boolean,false),
      coalesce(v_item->'invoice_address_snapshot','{}'::jsonb),coalesce(v_item->'site_address_snapshot','{}'::jsonb),
      nullif(v_item->>'consolidated_invoice_group_key',''),coalesce(nullif(v_item->>'adapter_key',''),'gridex_billing_partner_v1'),
      coalesce(nullif(v_item->>'payload_version',''),'billing_export_item_v4c'),coalesce(v_item->'adapter_payload_snapshot','{}'::jsonb),
      nullif(v_item->>'external_reference',''),coalesce(v_item->'payload_snapshot','{}'::jsonb),
      coalesce(nullif(v_item->>'export_status',''),'not_queued'),nullif(v_item->>'idempotency_key',''),
      coalesce(nullif(v_item->>'created_at','')::timestamptz,now()),coalesce(nullif(v_item->>'updated_at','')::timestamptz,now())
    );
    v_rows:=v_rows+1;
  end loop;

  if v_rows<>coalesce((p_run->>'rows_total')::integer,0) then
    raise exception using errcode='23514',message='export_run_item_count_mismatch';
  end if;
  return to_jsonb(v_run);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_invoice_export_graph_v1(p_run jsonb, p_items jsonb, p_invoices jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_company_id uuid := nullif(p_run->>'company_id', '')::uuid;
  v_idempotency_key text := nullif(p_run->>'idempotency_key', '');
  v_core_run jsonb := p_run - array['legacy_run', 'legacy_items'];
  v_logical_items jsonb;
  v_logical_invoices jsonb;
  v_payload_hash text;
  v_existing_run_id uuid;
  v_existing_payload_hash text;
  v_legacy_existing_id uuid;
  v_core_result jsonb;
  v_legacy_result jsonb;
  v_event_id uuid;
  v_item jsonb;
  v_invoice jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'invoice_export_graph_service_role_required';
  end if;
  if v_company_id is null or v_idempotency_key is null then
    raise exception using
      errcode = '22023',
      message = 'invoice_export_company_idempotency_required';
  end if;
  if jsonb_typeof(coalesce(p_run->'legacy_run', 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_run->'legacy_items', 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_items, 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_invoices, 'null'::jsonb)) <> 'array' then
    raise exception using
      errcode = '22023',
      message = 'invoice_export_graph_payload_invalid';
  end if;
  if jsonb_array_length(p_items) <> jsonb_array_length(p_invoices) then
    raise exception using
      errcode = '22023',
      message = 'invoice_export_graph_array_mismatch';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item->'total_kwh') <> 'number'
       or jsonb_typeof(v_item->'amount_ex_vat') <> 'number'
       or jsonb_typeof(v_item->'vat_amount') <> 'number'
       or jsonb_typeof(v_item->'amount_inc_vat') <> 'number'
       or nullif(v_item->>'currency', '') is null then
      raise exception using
        errcode = '22023',
        message = 'invoice_export_item_financial_values_required';
    end if;
  end loop;
  for v_invoice in select value from jsonb_array_elements(p_invoices)
  loop
    if jsonb_typeof(v_invoice->'total_kwh') <> 'number'
       or jsonb_typeof(v_invoice->'amount_ex_vat') <> 'number'
       or jsonb_typeof(v_invoice->'vat_amount') <> 'number'
       or jsonb_typeof(v_invoice->'amount_inc_vat') <> 'number'
       or nullif(v_invoice->>'currency', '') is null then
      raise exception using
        errcode = '22023',
        message = 'customer_invoice_financial_values_required';
    end if;
  end loop;

  select coalesce(
    jsonb_agg(
      value - array['id', 'metadata', 'idempotency_key']
      order by value->>'billing_underlay_id'
    ),
    '[]'::jsonb
  )
  into v_logical_items
  from jsonb_array_elements(p_items);

  select coalesce(
    jsonb_agg(
      value - array['invoice_export_item_id', 'metadata']
      order by value->>'customer_id', value->>'period_start'
    ),
    '[]'::jsonb
  )
  into v_logical_invoices
  from jsonb_array_elements(p_invoices);

  v_payload_hash := encode(
    digest(
      jsonb_build_object(
        'run',
          v_core_run - array[
            'id',
            'requested_by',
            'idempotency_key',
            'payload_hash'
          ],
        'items', v_logical_items,
        'invoices', v_logical_invoices
      )::text,
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(
    hashtextextended(v_company_id::text || ':' || v_idempotency_key, 0)
  );

  select run.id, run.payload_hash
  into v_existing_run_id, v_existing_payload_hash
  from public.invoice_export_runs run
  where run.company_id = v_company_id
    and run.idempotency_key = v_idempotency_key
  for update;

  if v_existing_run_id is not null
     and v_existing_payload_hash is not null
     and v_existing_payload_hash <> v_payload_hash then
    raise exception using
      errcode = '23505',
      message = 'invoice_export_idempotency_payload_mismatch';
  end if;

  -- If a compatibility run predates the canonical graph, preserve its durable
  -- identity when creating the canonical side.
  select run.id
  into v_legacy_existing_id
  from public.billing_export_runs run
  where run.company_id = v_company_id
    and run.idempotency_key = v_idempotency_key
  for update;
  if v_existing_run_id is null and v_legacy_existing_id is not null then
    v_core_run := jsonb_set(
      v_core_run,
      '{id}',
      to_jsonb(v_legacy_existing_id::text),
      true
    );
  end if;

  v_core_result :=
    public.gridex_create_invoice_export_graph_v1_core(
      v_core_run,
      p_items,
      p_invoices
    );
  v_existing_run_id := nullif(v_core_result->>'run_id', '')::uuid;
  if v_existing_run_id is null then
    raise exception using
      errcode = '23502',
      message = 'invoice_export_graph_result_missing_run_id';
  end if;

  update public.invoice_export_runs
  set payload_hash = coalesce(payload_hash, v_payload_hash),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'payload_hash', v_payload_hash,
          'canonical_runtime', 'gridex_create_invoice_export_graph_v1'
        )
  where id = v_existing_run_id
    and company_id = v_company_id;

  v_legacy_result := public.gridex_create_billing_export_run(
    jsonb_set(
      p_run->'legacy_run',
      '{id}',
      to_jsonb(v_existing_run_id::text),
      true
    ) || jsonb_build_object(
      'idempotency_key', v_idempotency_key,
      'payload_hash', v_payload_hash
    ),
    p_run->'legacy_items'
  );
  if nullif(v_legacy_result->>'id', '')::uuid
       is distinct from v_existing_run_id then
    raise exception using
      errcode = '23514',
      message = 'invoice_export_compatibility_run_identity_mismatch';
  end if;
  update public.billing_export_runs
  set payload_hash = coalesce(payload_hash, v_payload_hash),
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'canonical_invoice_export_run_id', v_existing_run_id,
          'payload_hash', v_payload_hash
        )
  where id = v_existing_run_id
    and company_id = v_company_id;
  select to_jsonb(run)
  into v_legacy_result
  from public.billing_export_runs run
  where run.id = v_existing_run_id
    and run.company_id = v_company_id;

  if not coalesce((v_core_result->>'existing')::boolean, false) then
    insert into public.domain_events(
      company_id,
      event_type,
      aggregate_type,
      aggregate_id,
      actor_user_id,
      source,
      idempotency_key,
      payload
    ) values (
      v_company_id,
      'invoice.export_graph.created',
      'invoice_export_run',
      v_existing_run_id,
      nullif(p_run->>'requested_by', '')::uuid,
      'gridex_create_invoice_export_graph_v1',
      'invoice-export-created:' || v_existing_run_id::text,
      jsonb_build_object(
        'invoice_export_run_id', v_existing_run_id,
        'item_count', jsonb_array_length(p_items),
        'payload_hash', v_payload_hash
      )
    ) returning id into v_event_id;

    insert into public.event_outbox(
      company_id,
      domain_event_id,
      destination_type,
      destination_key,
      payload
    ) values (
      v_company_id,
      v_event_id,
      'webhook',
      'invoice.export_graph.created',
      jsonb_build_object(
        'domain_event_id', v_event_id,
        'event_type', 'invoice.export_graph.created',
        'invoice_export_run_id', v_existing_run_id
      )
    ) on conflict do nothing;
  end if;

  return v_core_result || jsonb_build_object(
    'payload_hash', v_payload_hash,
    'legacy_run', v_legacy_result
  );
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_create_invoice_export_graph_v1_core(p_run jsonb, p_items jsonb, p_invoices jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_company_id uuid:=nullif(p_run->>'company_id','')::uuid;
  v_run_id uuid:=coalesce(nullif(p_run->>'id','')::uuid,gen_random_uuid());
  v_idempotency_key text:=nullif(p_run->>'idempotency_key','');
  v_existing_id uuid;
  v_item jsonb;
  v_invoice jsonb;
  v_underlay public.billing_underlays%rowtype;
  v_export_item_id uuid;
  v_count integer:=0;
begin
  if auth.role()<>'service_role' then
    raise exception using errcode='42501',message='invoice_export_graph_service_role_required';
  end if;
  if v_company_id is null or v_idempotency_key is null then
    raise exception using errcode='22023',message='invoice_export_company_idempotency_required';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array'
     or jsonb_typeof(coalesce(p_invoices,'[]'::jsonb))<>'array'
     or jsonb_array_length(coalesce(p_items,'[]'::jsonb))<>jsonb_array_length(coalesce(p_invoices,'[]'::jsonb)) then
    raise exception using errcode='22023',message='invoice_export_graph_array_mismatch';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text||':'||v_idempotency_key,0));
  select id into v_existing_id from public.invoice_export_runs where company_id=v_company_id and idempotency_key=v_idempotency_key;
  if v_existing_id is not null then return jsonb_build_object('run_id',v_existing_id,'existing',true); end if;

  insert into public.invoice_export_runs(
    id,company_id,provider,environment,billing_month,financing_mode,status,total_items,readiness_snapshot,metadata,requested_by,idempotency_key
  ) values (
    v_run_id,v_company_id,coalesce(nullif(p_run->>'provider',''),'capway_aptic'),coalesce(nullif(p_run->>'environment',''),'test'),p_run->>'billing_month',
    coalesce(nullif(p_run->>'financing_mode',''),'invoice_service'),'draft',jsonb_array_length(p_items),coalesce(p_run->'readiness_snapshot','{}'::jsonb),
    coalesce(p_run->'metadata','{}'::jsonb),nullif(p_run->>'requested_by','')::uuid,v_idempotency_key
  );

  for v_item,v_invoice in
    select i.value,n.value from jsonb_array_elements(p_items) with ordinality i(value,ordinality)
    join jsonb_array_elements(p_invoices) with ordinality n(value,ordinality) using(ordinality)
  loop
    v_export_item_id:=nullif(v_item->>'id','')::uuid;
    select * into v_underlay from public.billing_underlays
    where id=nullif(v_item->>'billing_underlay_id','')::uuid and company_id=v_company_id for share;
    if not found
       or v_underlay.customer_id is distinct from nullif(v_item->>'customer_id','')::uuid
       or coalesce(v_underlay.customer_contract_id,v_underlay.contract_id) is distinct from nullif(v_item->>'customer_contract_id','')::uuid then
      raise exception using errcode='23514',message='invoice_export_underlay_customer_contract_mismatch';
    end if;

    insert into public.invoice_export_items(
      id,company_id,export_run_id,customer_id,billing_underlay_id,pricing_run_id,customer_contract_id,metering_point_id,period_start,period_end,total_kwh,currency,
      provider,environment,status,financing_mode,amount_ex_vat,vat_amount,amount_inc_vat,idempotency_key,metadata
    ) values (
      v_export_item_id,v_company_id,v_run_id,nullif(v_item->>'customer_id','')::uuid,v_underlay.id,nullif(v_item->>'pricing_run_id','')::uuid,
      nullif(v_item->>'customer_contract_id','')::uuid,nullif(v_item->>'metering_point_id','')::uuid,nullif(v_item->>'period_start','')::date,nullif(v_item->>'period_end','')::date,
      nullif(v_item->>'total_kwh','')::numeric,coalesce(nullif(v_item->>'currency',''),'SEK'),coalesce(nullif(v_item->>'provider',''),'capway_aptic'),
      coalesce(nullif(v_item->>'environment',''),'test'),'pending',coalesce(nullif(v_item->>'financing_mode',''),'invoice_service'),
      coalesce(nullif(v_item->>'amount_ex_vat','')::numeric,0),coalesce(nullif(v_item->>'vat_amount','')::numeric,0),coalesce(nullif(v_item->>'amount_inc_vat','')::numeric,0),
      nullif(v_item->>'idempotency_key',''),coalesce(v_item->'metadata','{}'::jsonb)
    );

    if nullif(v_invoice->>'invoice_export_item_id','')::uuid is distinct from v_export_item_id
       or nullif(v_invoice->>'customer_id','')::uuid is distinct from v_underlay.customer_id
       or nullif(v_invoice->>'customer_contract_id','')::uuid is distinct from coalesce(v_underlay.customer_contract_id,v_underlay.contract_id) then
      raise exception using errcode='23514',message='customer_invoice_export_identity_mismatch';
    end if;

    insert into public.customer_invoices(
      company_id,customer_id,contract_id,customer_contract_id,billing_underlay_id,partner_export_id,partner_invoice_reference,invoice_reference,
      invoice_export_item_id,canonical_export_item_id,period_start,period_end,total_kwh,amount_ex_vat,vat_amount,amount_inc_vat,currency,status,source_system,metadata,updated_at
    ) values (
      v_company_id,v_underlay.customer_id,coalesce(v_underlay.customer_contract_id,v_underlay.contract_id),coalesce(v_underlay.customer_contract_id,v_underlay.contract_id),
      v_underlay.id,null,
      coalesce(nullif(v_invoice->>'partner_invoice_reference',''),'pending:'||v_export_item_id::text),
      coalesce(nullif(v_invoice->>'invoice_reference',''),'draft:'||v_export_item_id::text),
      v_export_item_id,v_export_item_id,nullif(v_invoice->>'period_start','')::date,nullif(v_invoice->>'period_end','')::date,nullif(v_invoice->>'total_kwh','')::numeric,
      coalesce(nullif(v_invoice->>'amount_ex_vat','')::numeric,0),coalesce(nullif(v_invoice->>'vat_amount','')::numeric,0),coalesce(nullif(v_invoice->>'amount_inc_vat','')::numeric,0),
      coalesce(nullif(v_invoice->>'currency',''),'SEK'),'draft','canonical_invoice_export',coalesce(v_invoice->'metadata','{}'::jsonb),now()
    );
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object('run_id',v_run_id,'existing',false,'item_count',v_count);
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_customer_contract_chain_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_customer_id uuid:=nullif(v_row->>'customer_id','')::uuid;
  v_contract_id uuid:=coalesce(
    nullif(v_row->>'customer_contract_id','')::uuid,
    nullif(v_row->>'contract_id','')::uuid
  );
  v_metering_point_id uuid:=nullif(v_row->>'metering_point_id','')::uuid;
  v_underlay_id uuid:=nullif(v_row->>'billing_underlay_id','')::uuid;
  v_export_item_id uuid:=coalesce(
    nullif(v_row->>'invoice_export_item_id','')::uuid,
    nullif(v_row->>'canonical_export_item_id','')::uuid
  );
begin
  if v_company_id is null or v_customer_id is null then
    raise exception using errcode='23502',message='customer_chain_company_customer_required';
  end if;
  if v_contract_id is not null and not exists(
    select 1 from public.customer_contracts cc
    where cc.id=v_contract_id
      and cc.company_id=v_company_id
      and cc.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_contract_mismatch';
  end if;
  if v_metering_point_id is not null and not exists(
    select 1 from public.metering_points mp
    where mp.id=v_metering_point_id
      and mp.company_id=v_company_id
      and mp.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_metering_point_mismatch';
  end if;
  if v_underlay_id is not null and not exists(
    select 1 from public.billing_underlays bu
    where bu.id=v_underlay_id
      and bu.company_id=v_company_id
      and bu.customer_id=v_customer_id
      and (
        v_contract_id is null
        or coalesce(bu.customer_contract_id,bu.contract_id)=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_underlay_mismatch';
  end if;
  if v_export_item_id is not null and not exists(
    select 1 from public.invoice_export_items iei
    where iei.id=v_export_item_id
      and iei.company_id=v_company_id
      and iei.customer_id=v_customer_id
      and (
        v_contract_id is null
        or iei.customer_contract_id=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_export_item_mismatch';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_spot_price_month_server_aggregate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_calc record;
begin
  if tg_op='UPDATE' then
    if old.status='locked' then
      return new;
    end if;

    -- Locking/annotation-only updates must be persisted verbatim.
    if (to_jsonb(new) - array['status','locked_at','locked_by','lock_reason','updated_at'])
       = (to_jsonb(old) - array['status','locked_at','locked_by','lock_reason','updated_at'])
       and (
         new.status is distinct from old.status
         or new.locked_at is distinct from old.locked_at
         or new.locked_by is distinct from old.locked_by
         or new.lock_reason is distinct from old.lock_reason
       ) then
      return new;
    end if;
  end if;

  -- Canonicalize aggregate fields in NEW instead of replacing/cancelling the row operation.
  select * into strict v_calc
  from private.gridex_calculate_spot_price_month_v1(new.source,new.price_area,new.billing_month);

  new.period_start := v_calc.period_start;
  new.period_end := v_calc.period_end;
  new.average_sek_per_kwh := v_calc.average_sek_per_kwh;
  new.min_sek_per_kwh := v_calc.min_sek_per_kwh;
  new.max_sek_per_kwh := v_calc.max_sek_per_kwh;
  new.interval_count := v_calc.interval_count;
  new.expected_interval_count := v_calc.expected_interval_count;
  new.covered_duration_minutes := v_calc.covered_duration_minutes;
  new.expected_duration_minutes := v_calc.expected_duration_minutes;
  new.quality_issues := v_calc.quality_issues;
  new.provider_fetched_at := v_calc.provider_fetched_at;
  new.verified_at := v_calc.verified_at;
  new.status := v_calc.status;
  new.source_checksum := v_calc.source_checksum;
  new.updated_at := v_calc.updated_at;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_supplier_utilts_outbound_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_code text;
  v_requested text;
  v_resolution text;
  v_expected_appref text;
  v_capability_count integer;
  v_operational boolean;
begin
  if new.direction <> 'outbound' or upper(coalesce(new.message_family,'')) <> 'UTILTS' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status in ('sent','acknowledged','received','validated') then
    return new;
  end if;

  v_code := upper(coalesce(new.message_code,''));
  v_operational := new.grid_owner_data_request_id is not null
    or lower(coalesce(new.process_type,'')) = 'meter_values_request';

  if not v_operational then
    return new;
  end if;

  if v_code = 'E66' then
    raise exception 'utilts_e66_supplier_outbound_not_allowed';
  end if;

  if v_code <> 'E73' then
    raise exception 'utilts_supplier_operational_outbound_not_allowed:%', v_code;
  end if;

  v_requested := upper(coalesce(
    new.parsed_payload->>'requestedMessageCode',
    new.parsed_payload->>'requested_message_code',
    ''
  ));
  if v_requested not in ('S02','E66') then
    raise exception 'utilts_e73_requested_message_required';
  end if;

  if coalesce((new.parsed_payload->>'bilateralCapabilityVerified')::boolean,false) is not true then
    raise exception 'utilts_e73_bilateral_capability_required';
  end if;
  if new.company_id is null then
    raise exception 'utilts_e73_company_required';
  end if;

  select count(*) into v_capability_count
  from public.tenant_message_capabilities c
  where c.company_id = new.company_id
    and c.environment = new.environment
    and upper(c.message_family) = 'UTILTS'
    and upper(c.message_code) = 'E73'
    and lower(c.direction) = 'outbound'
    and c.is_enabled = true
    and c.bilateral = true
    and (c.valid_from is null or c.valid_from <= now())
    and (c.valid_to is null or c.valid_to > now());

  if v_capability_count <> 1 then
    raise exception 'utilts_e73_bilateral_capability_invalid:%', v_capability_count;
  end if;

  v_resolution := upper(coalesce(
    new.parsed_payload->>'resolution',
    new.parsed_payload->>'readingFrequency',
    ''
  ));
  if v_requested = 'S02' then
    v_expected_appref := '23-DDQ-S02-S';
  elsif v_resolution in ('15','PT15M','QUARTER_HOUR','QUARTER-HOURLY','QUARTER_HOURLY','KVART') then
    v_expected_appref := '23-DDQ-E66-T';
  else
    v_expected_appref := '23-DDQ-E66-S';
  end if;

  if upper(coalesce(new.application_reference,'')) = '23-DDQ-UTILTS' then
    raise exception 'utilts_generic_application_reference_forbidden';
  end if;
  if upper(coalesce(new.application_reference,'')) <> v_expected_appref then
    raise exception 'utilts_e73_application_reference_mismatch:expected=% actual=%', v_expected_appref, coalesce(new.application_reference,'');
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_guard_metering_value_source_tenant_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.metering_values mv
    where mv.id = new.metering_value_id and mv.company_id = new.company_id
  ) then
    raise exception 'metering_value_source_metering_value_tenant_mismatch' using errcode='23503';
  end if;
  if not exists (
    select 1 from public.normalized_metering_values nmv
    where nmv.id = new.normalized_metering_value_id and nmv.company_id = new.company_id
  ) then
    raise exception 'metering_value_source_normalized_value_tenant_mismatch' using errcode='23503';
  end if;
  if not exists (
    select 1 from public.ediel_messages em
    where em.id = new.source_ediel_message_id and em.company_id = new.company_id
  ) then
    raise exception 'metering_value_source_ediel_message_tenant_mismatch' using errcode='23503';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_ingest_metering_value_atomic(p_payload jsonb)
 RETURNS metering_values
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_company_id uuid := nullif(p_payload->>'company_id','')::uuid;
  v_customer_id uuid := nullif(p_payload->>'customer_id','')::uuid;
  v_site_id uuid := nullif(p_payload->>'site_id','')::uuid;
  v_customer_site_id uuid := nullif(p_payload->>'customer_site_id','')::uuid;
  v_metering_point_id uuid := nullif(p_payload->>'metering_point_id','')::uuid;
  v_key text := nullif(p_payload->>'canonical_dedupe_key','');
  v_existing public.metering_values%rowtype;
  v_inserted public.metering_values%rowtype;
  v_revision integer := 1;
  v_direction text := coalesce(nullif(p_payload->>'direction',''),case when p_payload->>'reading_type'='production' then 'production' else 'consumption' end);
  v_unit text := coalesce(nullif(p_payload->>'unit',''),'kWh');
  v_raw jsonb := coalesce(p_payload->'raw_payload','{}'::jsonb);
  v_normalized_id uuid;
  v_source_message_id uuid := nullif(p_payload->>'source_ediel_message_id','')::uuid;
  v_source_tx text := nullif(p_payload->>'source_transaction_reference','');
  v_source_line text := nullif(p_payload->>'source_line_reference','');
begin
  if v_company_id is null or v_customer_id is null or v_metering_point_id is null or v_key is null then
    raise exception 'metering_company_customer_point_key_required' using errcode='22023';
  end if;
  if not exists(select 1 from public.customers where company_id=v_company_id and id=v_customer_id) then
    raise exception 'metering_customer_tenant_mismatch' using errcode='23503';
  end if;
  if not exists(select 1 from public.metering_points where company_id=v_company_id and id=v_metering_point_id and customer_id=v_customer_id) then
    raise exception 'metering_point_tenant_or_customer_mismatch' using errcode='23503';
  end if;
  if (p_payload->>'period_start')::timestamptz >= (p_payload->>'period_end')::timestamptz then
    raise exception 'metering_period_invalid' using errcode='22023';
  end if;
  if v_direction not in ('consumption','production','net_consumption','net_production') then
    raise exception 'metering_direction_invalid' using errcode='22023';
  end if;
  if v_unit not in ('Wh','kWh','MWh') then raise exception 'metering_unit_invalid' using errcode='22023'; end if;

  select * into v_existing
    from public.metering_values
   where company_id=v_company_id and canonical_dedupe_key=v_key and is_current=true
   order by created_at desc,id desc limit 1 for update;

  if found and v_existing.value_kwh is not distinct from (p_payload->>'value_kwh')::numeric
           and v_existing.quality_code is not distinct from nullif(p_payload->>'quality_code','') then
    if v_source_message_id is not null then
      select id into v_normalized_id
        from public.normalized_metering_values
       where company_id=v_company_id
         and source_metering_value_id=v_existing.id
         and revision_status='current'
       order by created_at desc,id desc
       limit 1;
      if v_normalized_id is null then
        raise exception 'atomic_metering_projection_missing_for_existing_value' using errcode='23503';
      end if;
      insert into public.metering_value_sources(
        company_id,metering_value_id,normalized_metering_value_id,source_ediel_message_id,
        source_transaction_reference,source_line_reference,source_type
      ) values (
        v_company_id,v_existing.id,v_normalized_id,v_source_message_id,
        v_source_tx,v_source_line,coalesce(nullif(p_payload->>'source_system',''),'grid_owner')
      ) on conflict do nothing;
    end if;
    return v_existing;
  end if;

  if v_existing.id is not null then
    v_revision := coalesce(v_existing.revision_number,1)+1;
    update public.metering_values
       set is_current=false,value_status='replaced',revision_status='replaced',
           correction_reason=coalesce(nullif(p_payload->>'correction_reason',''),'Nytt mätvärde ersatte tidigare revision.')
     where id=v_existing.id and company_id=v_company_id;
    update public.normalized_metering_values
       set revision_status='replaced',status='replaced',updated_at=now()
     where company_id=v_company_id and source_metering_value_id=v_existing.id and revision_status='current';
  end if;

  insert into public.metering_values(
    company_id,customer_id,site_id,customer_site_id,metering_point_id,source_request_id,grid_owner_id,reading_type,
    value_kwh,quality_code,read_at,period_start,period_end,source_system,raw_payload,source_ediel_message_id,
    source_transaction_reference,source_line_reference,price_area,resolution,canonical_dedupe_key,is_current,previous_value_id,
    revision_number,correction_reason,value_status,revision_status,billing_status,register_code,product_code,direction,unit,created_by
  ) values (
    v_company_id,v_customer_id,v_site_id,v_customer_site_id,v_metering_point_id,nullif(p_payload->>'source_request_id','')::uuid,
    nullif(p_payload->>'grid_owner_id','')::uuid,coalesce(nullif(p_payload->>'reading_type',''),'consumption'),
    (p_payload->>'value_kwh')::numeric,nullif(p_payload->>'quality_code',''),(p_payload->>'read_at')::timestamptz,
    (p_payload->>'period_start')::timestamptz,(p_payload->>'period_end')::timestamptz,coalesce(nullif(p_payload->>'source_system',''),'grid_owner'),
    v_raw,v_source_message_id,v_source_tx,
    v_source_line,nullif(p_payload->>'price_area',''),nullif(p_payload->>'resolution',''),v_key,true,
    v_existing.id,v_revision,case when v_existing.id is null then null else coalesce(nullif(p_payload->>'correction_reason',''),'Korrigerat mätvärde.') end,
    'current','current','pending_match',nullif(p_payload->>'register_code',''),nullif(p_payload->>'product_code',''),v_direction,v_unit,
    nullif(p_payload->>'created_by','')::uuid
  ) returning * into v_inserted;

  if v_existing.id is not null then
    update public.metering_values set replaced_by_value_id=v_inserted.id where company_id=v_company_id and id=v_existing.id;
    update public.normalized_metering_values set replaced_by_value_id=v_inserted.id where company_id=v_company_id and source_metering_value_id=v_existing.id;
  end if;

  insert into public.normalized_metering_values(
    company_id,customer_id,customer_site_id,site_id,metering_point_id,facility_id,price_area,grid_area,period_start,period_end,
    resolution,quantity_kwh,quality_status,source_type,source_message_id,source_transaction_reference,source_line_reference,
    source_metering_value_id,raw_payload,status,revision_status,billing_status,register_code,product_code,direction,unit,
    canonical_dedupe_key,previous_value_id,revision_number,created_by
  ) values (
    v_company_id,v_customer_id,v_customer_site_id,v_site_id,v_metering_point_id,nullif(p_payload->>'facility_id',''),
    nullif(p_payload->>'price_area',''),nullif(p_payload->>'grid_area',''),(p_payload->>'period_start')::timestamptz,
    (p_payload->>'period_end')::timestamptz,nullif(p_payload->>'resolution',''),(p_payload->>'value_kwh')::numeric,
    nullif(p_payload->>'quality_code',''),coalesce(nullif(p_payload->>'source_system',''),'grid_owner'),
    v_source_message_id,v_source_tx,
    v_source_line,v_inserted.id,v_raw,'stored','current','pending_match',
    nullif(p_payload->>'register_code',''),nullif(p_payload->>'product_code',''),v_direction,v_unit,v_key,v_existing.id,v_revision,
    nullif(p_payload->>'created_by','')::uuid
  ) returning id into v_normalized_id;

  if v_source_message_id is not null then
    insert into public.metering_value_sources(
      company_id,metering_value_id,normalized_metering_value_id,source_ediel_message_id,
      source_transaction_reference,source_line_reference,source_type
    ) values (
      v_company_id,v_inserted.id,v_normalized_id,v_source_message_id,
      v_source_tx,v_source_line,coalesce(nullif(p_payload->>'source_system',''),'grid_owner')
    ) on conflict do nothing;
  end if;

  return v_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_lock_pricing_run(p_company_id uuid, p_pricing_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_run public.pricing_runs%rowtype;
  v_underlay public.billing_underlays%rowtype;
  v_month text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_pricing_run_id::text,0));
  select * into v_run from public.pricing_runs where id=p_pricing_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='pricing_run_not_found_for_tenant'; end if;
  if v_run.status not in ('success','locked') then raise exception using errcode='23514',message='only_successful_pricing_run_can_be_locked'; end if;
  select * into v_underlay from public.billing_underlays where id=v_run.billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='pricing_underlay_not_found'; end if;
  v_month:=to_char(v_run.billing_period_start at time zone 'Europe/Stockholm','YYYY-MM');
  if v_run.status='locked' then
    return jsonb_build_object('pricing_run_id',v_run.id,'billing_underlay_id',v_underlay.id,'billing_month',v_month,'status','locked');
  end if;

  insert into public.price_period_locks(company_id,billing_month,lock_scope,status,locked_by,locked_at)
  values(p_company_id,v_month,'pricing_preview','locked',p_actor_user_id,now())
  on conflict(company_id,billing_month,lock_scope) do update set status='locked',locked_by=excluded.locked_by,locked_at=excluded.locked_at;

  insert into public.contract_charge_ledger(
    company_id,customer_contract_id,component_key,event_key,pricing_run_id,amount_ex_vat,metadata
  )
  select p_company_id,v_underlay.contract_id,
    coalesce(nullif(l.metadata->>'component_key',''),l.line_type||':'||encode(digest(lower(l.description),'sha256'),'hex')),
    case
      when coalesce(l.metadata->>'lifecycle','')='event_only' then coalesce(nullif(l.metadata->>'billing_event_id',''),nullif(l.metadata->>'event',''),'event')
      else 'contract'
    end,v_run.id,l.amount_ex_vat,l.metadata
  from public.pricing_preview_lines l
  where l.pricing_run_id=v_run.id
    and coalesce(l.metadata->>'lifecycle','') in ('once_per_contract','one_time','event_only')
  on conflict(customer_contract_id,component_key,event_key) do nothing;

  update public.pricing_runs set status='locked',locked_at=now() where id=v_run.id;
  update public.billing_underlays set readiness_status='ready',updated_at=now()
  where id=v_underlay.id and company_id=p_company_id;
  return jsonb_build_object('pricing_run_id',v_run.id,'billing_underlay_id',v_underlay.id,'billing_month',v_month,'status','locked');
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_persist_pricing_run(p_company_id uuid, p_billing_underlay_id uuid, p_result jsonb, p_pricing_snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_underlay public.billing_underlays%rowtype;
  v_run_id uuid;
  v_final_status text:=coalesce(nullif(p_result->>'status',''),'failed');
  v_rows integer;
begin
  if p_company_id is null or p_billing_underlay_id is null then
    raise exception using errcode='22023',message='company_and_billing_underlay_required';
  end if;
  if v_final_status not in ('success','failed','needs_review') then
    raise exception using errcode='22023',message='invalid_pricing_result_status';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_billing_underlay_id::text,0));
  select * into v_underlay from public.billing_underlays
  where id=p_billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found_for_tenant'; end if;
  if v_underlay.contract_id is null or coalesce(v_underlay.contract_price_snapshot_id,v_underlay.pricing_snapshot_id) is null then
    raise exception using errcode='23514',message='exact_contract_and_price_snapshot_required';
  end if;
  if exists(select 1 from public.pricing_runs where company_id=p_company_id and billing_underlay_id=p_billing_underlay_id and status='locked') then
    raise exception using errcode='55000',message='pricing_run_locked';
  end if;

  insert into public.pricing_runs(
    company_id,billing_underlay_id,customer_id,billing_period_start,billing_period_end,status,
    total_ex_vat,vat_amount,total_inc_vat,warnings,errors,metadata
  ) values (
    p_company_id,p_billing_underlay_id,v_underlay.customer_id,v_underlay.billing_period_start,v_underlay.billing_period_end,
    case when v_final_status='success' then 'needs_review' else v_final_status end,
    coalesce((p_result->>'total_ex_vat')::numeric,0),coalesce((p_result->>'vat_amount')::numeric,0),
    coalesce((p_result->>'total_inc_vat')::numeric,0),coalesce(p_result->'warnings','[]'::jsonb),
    coalesce(p_result->'errors','[]'::jsonb),jsonb_build_object('source','pricing_core','atomic',true)
  ) returning id into v_run_id;

  insert into public.pricing_preview_lines(
    company_id,pricing_run_id,billing_underlay_id,line_type,description,quantity,unit,
    unit_price_ex_vat,amount_ex_vat,vat_rate,vat_amount,amount_inc_vat,sort_order,metadata
  )
  select p_company_id,v_run_id,p_billing_underlay_id,
    coalesce(nullif(x->>'line_type',''),'unknown'),coalesce(nullif(x->>'description',''),'Prisrad'),
    nullif(x->>'quantity','')::numeric,coalesce(nullif(x->>'unit',''),'st'),nullif(x->>'unit_price_ex_vat','')::numeric,
    coalesce(nullif(x->>'amount_ex_vat','')::numeric,0),coalesce(nullif(x->>'vat_rate','')::numeric,0),
    coalesce(nullif(x->>'vat_amount','')::numeric,0),coalesce(nullif(x->>'amount_inc_vat','')::numeric,0),
    coalesce(nullif(x->>'sort_order','')::integer,100),coalesce(x->'metadata','{}'::jsonb)
  from jsonb_array_elements(coalesce(p_result->'lines','[]'::jsonb)) x;

  insert into public.pricing_interval_evidence(
    company_id,pricing_run_id,billing_underlay_id,billing_underlay_item_id,customer_contract_id,
    metering_interval_start,metering_interval_end,resolution,consumption_kwh,price_sek_per_kwh,
    amount_ex_vat,price_source_id,price_area,evidence_sha256
  )
  select p_company_id,v_run_id,p_billing_underlay_id,nullif(x->>'billing_underlay_item_id','')::uuid,
    v_underlay.contract_id,(x->>'metering_interval_start')::timestamptz,(x->>'metering_interval_end')::timestamptz,
    x->>'resolution',(x->>'consumption_kwh')::numeric,(x->>'price_sek_per_kwh')::numeric,
    (x->>'amount_ex_vat')::numeric,nullif(x->>'price_source_id','')::uuid,x->>'price_area',
    encode(digest((x||jsonb_build_object('pricing_run_id',v_run_id))::text,'sha256'),'hex')
  from jsonb_array_elements(coalesce(p_result->'interval_evidence','[]'::jsonb)) x;

  if v_final_status='success' then
    update public.pricing_runs set status='superseded'
    where company_id=p_company_id and billing_underlay_id=p_billing_underlay_id and id<>v_run_id and status='success';
    update public.pricing_runs set status='success' where id=v_run_id;
    update public.billing_underlays set
      status='validated',readiness_status='ready',readiness_issues='[]'::jsonb,
      invoice_readiness_status='ready_for_invoice',invoice_readiness_issues='[]'::jsonb,
      calculated_total_sek_ex_vat=coalesce((p_result->>'total_ex_vat')::numeric,0),
      calculated_vat_sek=coalesce((p_result->>'vat_amount')::numeric,0),
      calculated_total_sek_inc_vat=coalesce((p_result->>'total_inc_vat')::numeric,0),
      pricing_snapshot=coalesce(p_pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_pricing_run_id',v_run_id,'latest_pricing_warnings',coalesce(p_result->'warnings','[]'::jsonb),
        'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ),updated_at=now()
    where id=p_billing_underlay_id and company_id=p_company_id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then raise exception using errcode='P0002',message='billing_underlay_atomic_update_failed'; end if;
  else
    update public.billing_underlays set
      pricing_snapshot=coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_failed_pricing_run_id',v_run_id,'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ),updated_at=now()
    where id=p_billing_underlay_id and company_id=p_company_id;
  end if;
  return v_run_id;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_reject_locked_market_price_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op='DELETE' then
    if old.status='locked' then
      raise exception 'locked_market_price_immutable' using errcode='55000';
    end if;
    return old;
  end if;
  if old.status='locked' and new is distinct from old then
    raise exception 'locked_market_price_immutable' using errcode='55000';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_store_billing_underlay(p_company_id uuid, p_underlay jsonb, p_items jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_id uuid;
  v_customer_id uuid := nullif(p_underlay->>'customer_id','')::uuid;
  v_metering_point_id uuid := nullif(p_underlay->>'metering_point_id','')::uuid;
  v_year integer := (p_underlay->>'underlay_year')::integer;
  v_month integer := (p_underlay->>'underlay_month')::integer;
  v_start_instant timestamptz := (p_underlay->>'billing_period_start')::timestamptz;
  v_end_instant timestamptz := (p_underlay->>'billing_period_end')::timestamptz;
  v_start_date date := (v_start_instant at time zone 'Europe/Stockholm')::date;
  v_end_date date := (v_end_instant at time zone 'Europe/Stockholm')::date;
  v_energy_direction text := coalesce(nullif(p_underlay->>'energy_direction',''),nullif(p_underlay#>>'{payload,energy_direction}',''),'consumption');
  v_settlement_type text := coalesce(nullif(p_underlay->>'settlement_type',''),nullif(p_underlay#>>'{payload,settlement_type}',''));
begin
  if p_company_id is null or v_customer_id is null or v_metering_point_id is null then
    raise exception 'billing_underlay_tenant_customer_meter_required' using errcode='22023';
  end if;
  if v_end_instant <= v_start_instant or v_end_date <= v_start_date then
    raise exception 'billing_underlay_invalid_segment' using errcode='22023';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then raise exception 'billing_underlay_items_must_be_array' using errcode='22023'; end if;
  if v_energy_direction not in ('consumption','production','consumption_correction') then raise exception 'billing_underlay_invalid_energy_direction' using errcode='22023'; end if;
  if not exists(select 1 from public.customers where company_id=p_company_id and id=v_customer_id) then raise exception 'billing_underlay_customer_tenant_mismatch' using errcode='23503'; end if;
  if not exists(select 1 from public.metering_points where company_id=p_company_id and id=v_metering_point_id) then raise exception 'billing_underlay_meter_tenant_mismatch' using errcode='23503'; end if;

  insert into public.billing_underlays(
    company_id,customer_id,site_id,customer_site_id,metering_point_id,supply_period_id,contract_id,pricing_snapshot_id,
    price_plan_id,price_plan_version_id,price_book_id,contract_price_snapshot_id,billing_block_reason,campaign_id,price_area,
    energy_direction,settlement_type,underlay_month,underlay_year,billing_period_start,billing_period_end,status,readiness_status,
    readiness_issues,total_kwh,currency,source_system,source_meter_value_count,missing_values_count,payload,pricing_snapshot,
    received_at,validated_at,created_by,updated_by,updated_at
  ) values (
    p_company_id,v_customer_id,nullif(p_underlay->>'site_id','')::uuid,nullif(p_underlay->>'customer_site_id','')::uuid,v_metering_point_id,
    nullif(p_underlay->>'supply_period_id','')::uuid,nullif(p_underlay->>'contract_id','')::uuid,nullif(p_underlay->>'pricing_snapshot_id','')::uuid,
    nullif(p_underlay->>'price_plan_id','')::uuid,nullif(p_underlay->>'price_plan_version_id','')::uuid,nullif(p_underlay->>'price_book_id','')::uuid,
    nullif(p_underlay->>'contract_price_snapshot_id','')::uuid,nullif(p_underlay->>'billing_block_reason',''),nullif(p_underlay->>'campaign_id','')::uuid,
    nullif(p_underlay->>'price_area',''),v_energy_direction,v_settlement_type,v_month,v_year,v_start_date,v_end_date,
    coalesce(nullif(p_underlay->>'status',''),'pending'),coalesce(nullif(p_underlay->>'readiness_status',''),'blocked'),
    coalesce(p_underlay->'readiness_issues','[]'::jsonb),(p_underlay->>'total_kwh')::numeric,coalesce(nullif(p_underlay->>'currency',''),'SEK'),
    coalesce(nullif(p_underlay->>'source_system',''),'normalized_metering_values'),coalesce((p_underlay->>'source_meter_value_count')::integer,0),
    coalesce((p_underlay->>'missing_values_count')::integer,0),coalesce(p_underlay->'payload','{}'::jsonb)||jsonb_build_object(
      'billing_period_start_instant',v_start_instant,'billing_period_end_instant',v_end_instant,'billing_period_timezone','Europe/Stockholm','billing_period_end_exclusive',true
    ),coalesce(p_underlay->'pricing_snapshot','{}'::jsonb),coalesce((p_underlay->>'received_at')::timestamptz,now()),
    nullif(p_underlay->>'validated_at','')::timestamptz,p_actor_user_id,p_actor_user_id,now()
  )
  on conflict(company_id,customer_id,metering_point_id,underlay_year,underlay_month,billing_period_start,billing_period_end,energy_direction)
  do update set
    site_id=excluded.site_id,customer_site_id=excluded.customer_site_id,supply_period_id=excluded.supply_period_id,contract_id=excluded.contract_id,
    pricing_snapshot_id=excluded.pricing_snapshot_id,price_plan_id=excluded.price_plan_id,price_plan_version_id=excluded.price_plan_version_id,
    price_book_id=excluded.price_book_id,contract_price_snapshot_id=excluded.contract_price_snapshot_id,billing_block_reason=excluded.billing_block_reason,
    campaign_id=excluded.campaign_id,price_area=excluded.price_area,status=excluded.status,readiness_status=excluded.readiness_status,
    readiness_issues=excluded.readiness_issues,total_kwh=excluded.total_kwh,currency=excluded.currency,source_system=excluded.source_system,
    source_meter_value_count=excluded.source_meter_value_count,missing_values_count=excluded.missing_values_count,payload=excluded.payload,
    pricing_snapshot=excluded.pricing_snapshot,received_at=excluded.received_at,validated_at=excluded.validated_at,updated_by=p_actor_user_id,updated_at=now()
  returning id into v_id;

  delete from public.billing_underlay_items where company_id=p_company_id and billing_underlay_id=v_id;
  insert into public.billing_underlay_items
  select (jsonb_populate_record(null::public.billing_underlay_items,
    item || jsonb_build_object('id',gen_random_uuid(),'company_id',p_company_id,'billing_underlay_id',v_id,'created_at',now(),'updated_at',now()))).*
  from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) item;

  insert into public.billing_underlay_events(company_id,billing_underlay_id,event_type,message,metadata,created_by)
  values(p_company_id,v_id,'underlay_generated',case when p_underlay->>'readiness_status'='ready' then 'Fakturaunderlag är redo för prisberäkning.' else 'Fakturaunderlag är blockerat.' end,
    jsonb_build_object('billing_period_start',v_start_date,'billing_period_end',v_end_date,'billing_period_start_instant',v_start_instant,'billing_period_end_instant',v_end_instant,'billing_period_timezone','Europe/Stockholm','billing_period_end_exclusive',true,'energy_direction',v_energy_direction,'source_rows',jsonb_array_length(coalesce(p_items,'[]'::jsonb))),p_actor_user_id);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_store_billing_underlay_batch(p_company_id uuid, p_commands jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_command jsonb;
  v_ids jsonb:='[]'::jsonb;
  v_id uuid;
begin
  if jsonb_typeof(coalesce(p_commands,'[]'::jsonb))<>'array' then
    raise exception using errcode='22023',message='billing_underlay_commands_must_be_array';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':billing-underlay-batch',0));
  for v_command in select value from jsonb_array_elements(coalesce(p_commands,'[]'::jsonb)) loop
    v_id:=public.gridex_store_billing_underlay(
      p_company_id,
      coalesce(v_command->'underlay','{}'::jsonb),
      coalesce(v_command->'items','[]'::jsonb),
      p_actor_user_id
    );
    v_ids:=v_ids||jsonb_build_array(v_id::text);
  end loop;
  return v_ids;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_sync_supply_customer_contract_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.contract_id is not null and new.customer_contract_id is not null
     and new.contract_id is distinct from new.customer_contract_id then
    raise exception using errcode='23514',message='supply_contract_alias_mismatch';
  end if;
  new.customer_contract_id:=coalesce(new.customer_contract_id,new.contract_id);
  new.contract_id:=coalesce(new.contract_id,new.customer_contract_id);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_unlock_pricing_runs_for_month(p_company_id uuid, p_billing_month text, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_month_start date;
  v_month_end date;
  v_count integer;
begin
  if p_billing_month !~ '^\d{4}-\d{2}$' then
    raise exception 'billing_month must be formatted as YYYY-MM';
  end if;
  v_month_start := to_date(p_billing_month || '-01', 'YYYY-MM-DD');
  v_month_end := v_month_start + interval '1 month';

  perform set_config('app.gridex_pricing_maintenance', 'on', true);

  update public.pricing_runs
  set
    status = 'success',
    locked_at = null,
    metadata = metadata || jsonb_build_object(
      'unlocked_at', now(),
      'unlocked_by', p_actor_user_id,
      'unlock_reason', coalesce(p_reason, 'billing_period_unlocked')
    )
  where company_id = p_company_id
    and status = 'locked'
    and billing_period_start >= v_month_start
    and billing_period_start < v_month_end;

  get diagnostics v_count = row_count;

  perform set_config('app.gridex_pricing_maintenance', '', true);

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_validate_ediel_message_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare v_canonical boolean;
begin
  v_canonical := upper(coalesce(new.message_family,'')) in ('PRODAT','UTILTS','CONTRL','APERAK','UTILTS_ERR');
  if v_canonical then
    if new.company_id is null then raise exception 'canonical_ediel_company_required' using errcode='23502'; end if;
    if nullif(btrim(coalesce(new.environment,'')),'') is null then raise exception 'canonical_ediel_environment_required' using errcode='23502'; end if;
    if new.direction='outbound' then
      if new.canonical_rule_pack_id is null then raise exception 'canonical_ediel_rule_pack_required' using errcode='23502'; end if;
      if new.communication_route_id is null then raise exception 'canonical_ediel_route_required' using errcode='23502'; end if;
      if new.route_profile_id is null and nullif(new.execution_context_snapshot->>'routeProfileId','') is null then raise exception 'canonical_ediel_route_profile_required' using errcode='23502'; end if;
      if nullif(btrim(coalesce(new.application_reference,'')),'') is null then raise exception 'canonical_ediel_application_reference_required' using errcode='23502'; end if;
      if nullif(btrim(coalesce(new.source_operation_id,new.execution_context_snapshot->>'sourceOperationId','')),'') is null then raise exception 'canonical_ediel_source_operation_required' using errcode='23502'; end if;
      if new.raw_payload is not null and nullif(btrim(new.raw_payload),'') is not null then
        new.immutable_payload_hash := encode(digest(convert_to(new.raw_payload,'UTF8'),'sha256'),'hex');
        new.immutable_rendered_at := coalesce(new.immutable_rendered_at,now());
      end if;
    end if;
  end if;
  if tg_op='UPDATE' and old.immutable_payload_hash is not null then
    if new.raw_payload is distinct from old.raw_payload or new.immutable_payload_hash is distinct from old.immutable_payload_hash then
      raise exception 'immutable_ediel_payload_cannot_change' using errcode='23514';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.set_current_timestamp_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
